_AES_SB = [99, 124, 119, 123, 242, 107, 111, 197, 48, 1, 103, 43, 254, 215, 171, 118, 202, 130, 201, 125, 250, 89, 71, 240, 173, 212, 162, 175, 156, 164, 114, 192, 183, 253, 147, 38, 54, 63, 247, 204, 52, 165, 229, 241, 113, 216, 49, 21, 4, 199, 35, 195, 24, 150, 5, 154, 7, 18, 128, 226, 235, 39, 178, 117, 9, 131, 44, 26, 27, 110, 90, 160, 82, 59, 214, 179, 41, 227, 47, 132, 83, 209, 0, 237, 32, 252, 177, 91, 106, 203, 190, 57, 74, 76, 88, 207, 208, 239, 170, 251, 67, 77, 51, 133, 69, 249, 2, 127, 80, 60, 159, 168, 81, 163, 64, 143, 146, 157, 56, 245, 188, 182, 218, 33, 16, 255, 243, 210, 205, 12, 19, 236, 95, 151, 68, 23, 196, 167, 126, 61, 100, 93, 25, 115, 96, 129, 79, 220, 34, 42, 144, 136, 70, 238, 184, 20, 222, 94, 11, 219, 224, 50, 58, 10, 73, 6, 36, 92, 194, 211, 172, 98, 145, 149, 228, 121, 231, 200, 55, 109, 141, 213, 78, 169, 108, 86, 244, 234, 101, 122, 174, 8, 186, 120, 37, 46, 28, 166, 180, 198, 232, 221, 116, 31, 75, 189, 139, 138, 112, 62, 181, 102, 72, 3, 246, 14, 97, 53, 87, 185, 134, 193, 29, 158, 225, 248, 152, 17, 105, 217, 142, 148, 155, 30, 135, 233, 206, 85, 40, 223, 140, 161, 137, 13, 191, 230, 66, 104, 65, 153, 45, 15, 176, 84, 187, 22]
_AES_RC = [1, 2, 4, 8, 16, 32, 64, 128, 27, 54, 108, 216, 171, 77, 154, 47]

def _axt(a):
    return ((a << 1) ^ 0x1b) & 0xff if a & 0x80 else (a << 1) & 0xff

def _akx(key):
    w = list(key)
    for i in range(8, 60):
        t = w[(i-1)*4:i*4]
        if i % 8 == 0:
            t = [_AES_SB[t[1]] ^ _AES_RC[i//8-1], _AES_SB[t[2]], _AES_SB[t[3]], _AES_SB[t[0]]]
        elif i % 8 == 4:
            t = [_AES_SB[b] for b in t]
        for j in range(4):
            w.append(w[(i-8)*4+j] ^ t[j])
    return [w[i*4:(i+1)*4] for i in range(60)]

def _aeb(block, ek):
    s = list(block)
    def _ari(rnd):
        rk = b"".join(bytes(x) for x in ek[4*rnd:4*rnd+4])
        for i in range(16):
            s[i] ^= rk[i]
    def _srows():
        for r in (1,2,3):
            vals = [s[r+4*c] for c in range(4)]
            for c in range(4):
                s[r+4*c] = vals[(c+r)%4]
    def _mcols():
        for ci in range(4):
            a = s[4*ci:4*ci+4]
            s[4*ci+0] = _axt(a[0]) ^ _axt(a[1]) ^ a[1] ^ a[2] ^ a[3]
            s[4*ci+1] = a[0] ^ _axt(a[1]) ^ _axt(a[2]) ^ a[2] ^ a[3]
            s[4*ci+2] = a[0] ^ a[1] ^ _axt(a[2]) ^ _axt(a[3]) ^ a[3]
            s[4*ci+3] = _axt(a[0]) ^ a[0] ^ a[1] ^ a[2] ^ _axt(a[3])
    _ari(0)
    for rnd in range(1, 14):
        for i in range(16):
            s[i] = _AES_SB[s[i]]
        _srows(); _mcols(); _ari(rnd)
    for i in range(16):
        s[i] = _AES_SB[s[i]]
    _srows(); _ari(14)
    return bytes(s)

def _ghash(h, aad, ct):
    def _gm(a, b):
        z = [0]*16
        v = list(a)
        for x in range(128):
            if b[x>>3] & (0x80 >> (x & 7)):
                z = [v[y] ^ z[y] for y in range(16)]
            bit = v[15] & 1
            for j in range(15, 0, -1):
                v[j] = (v[j] >> 1) | ((v[j-1] << 7) & 0x80)
            v[0] >>= 1
            if bit:
                v[0] ^= 0xe1
        return z
    def p16(d):
        r = len(d) % 16
        return d + b"\x00" * (16 - r if r else 0)
    y = [0]*16
    hb = list(h)
    data = p16(aad) + p16(ct) + _st_.pack(">QQ", len(aad)*8, len(ct)*8)
    for i in range(0, len(data), 16):
        blk = list(data[i:i+16])
        y = [y[j] ^ blk[j] for j in range(16)]
        y = _gm(y, hb)
    return bytes(y)

def _agd(key, iv, ct, tag, aad=b"jocolo-v11-aad"):
    import hmac as _hm
    ek = _akx(list(key))
    hb = _aeb(b"\x00"*16, ek)
    etag = _ghash(hb, aad, ct)
    j0 = iv + b"\x00\x00\x00\x01"
    j0e = _aeb(j0, ek)
    etag = bytes(a ^ b for a, b in zip(etag, j0e))
    if not _hm.compare_digest(etag, tag):
        raise ValueError("tag fail")
    def cb(c):
        return _aeb(iv + _st_.pack(">I", c), ek)
    pt = bytearray()
    for i in range(0, len(ct), 16):
        ks = cb(i//16 + 2)
        ch = ct[i:i+16]
        pt.extend(b ^ k for b, k in zip(ch, ks))
    return bytes(pt)



def _cc20q(a, b, c, d):
    a = (a+b) & 0xFFFFFFFF; d ^= a; d = ((d << 16) | (d >> 16)) & 0xFFFFFFFF
    c = (c+d) & 0xFFFFFFFF; b ^= c; b = ((b << 12) | (b >> 20)) & 0xFFFFFFFF
    a = (a+b) & 0xFFFFFFFF; d ^= a; d = ((d << 8) | (d >> 24)) & 0xFFFFFFFF
    c = (c+d) & 0xFFFFFFFF; b ^= c; b = ((b << 7) | (b >> 25)) & 0xFFFFFFFF
    return a, b, c, d

def _cc20b(key, ctr, nonce):
    cs = b"expand 32-byte k"
    st = list(_st_.unpack("<4I", cs)) + list(_st_.unpack("<8I", key)) + [ctr] + list(_st_.unpack("<3I", nonce))
    w = st[:]
    for _ in range(10):
        w[0],w[4],w[8],w[12]  = _cc20q(w[0],w[4],w[8],w[12])
        w[1],w[5],w[9],w[13]  = _cc20q(w[1],w[5],w[9],w[13])
        w[2],w[6],w[10],w[14] = _cc20q(w[2],w[6],w[10],w[14])
        w[3],w[7],w[11],w[15] = _cc20q(w[3],w[7],w[11],w[15])
        w[0],w[5],w[10],w[15] = _cc20q(w[0],w[5],w[10],w[15])
        w[1],w[6],w[11],w[12] = _cc20q(w[1],w[6],w[11],w[12])
        w[2],w[7],w[8],w[13]  = _cc20q(w[2],w[7],w[8],w[13])
        w[3],w[4],w[9],w[14]  = _cc20q(w[3],w[4],w[9],w[14])
    return _st_.pack("<16I", *((w[i] + st[i]) & 0xFFFFFFFF for i in range(16)))

def _cc20d(data, key, nonce):
    out = bytearray()
    for i, off in enumerate(range(0, len(data), 64)):
        ks = _cc20b(key, i, nonce)
        ch = data[off:off+64]
        out.extend(b ^ k for b, k in zip(ch, ks))
    return bytes(out)



import hmac as _hmk

def _hkdf(ikm, length, salt, info):
    if not salt:
        salt = b"\x00" * 32
    prk = _hmk.new(salt, ikm, _h_.sha256).digest()
    t = b""
    okm = b""
    i = 1
    while len(okm) < length:
        t = _hmk.new(prk, t + info + bytes([i]), _h_.sha256).digest()
        okm += t
        i += 1
    return okm[:length]



def _xss(data, key):
    x = int.from_bytes(key[:8], "big") or 0xDEADBEEFCAFEBABE
    out = bytearray(len(data))
    for i, b in enumerate(data):
        x ^= (x << 13) & 0xFFFFFFFFFFFFFFFF
        x ^= x >> 7
        x ^= (x << 17) & 0xFFFFFFFFFFFFFFFF
        out[i] = b ^ (x & 0xFF)
    return bytes(out)



def _bun(data, key):
    import random as _rnd
    n = len(data)
    if not n:
        return data
    seed = int.from_bytes(_h_.sha256(key + b"permute_v11").digest()[:8], "big")
    rng = _rnd.Random(seed)
    idx = list(range(n))
    rng.shuffle(idx)
    out = bytearray(n)
    for np, op in enumerate(idx):
        out[op] = data[np]
    return bytes(out)


def _hkdf(ikm, length, salt, info):
    if not salt:
        salt = b"\x00" * 32
    prk = _h_.hmac_new = None
    import hmac as _hm
    prk = _hm.new(salt, ikm, _h_.sha256).digest()
    t = b""
    okm = b""
    i = 1
    while len(okm) < length:
        t = _hm.new(prk, t + info + bytes([i]), _h_.sha256).digest()
        okm += t
        i += 1
    return okm[:length]

try:
    _vsl = bytes.fromhex(__JSALT__)
    _vmk_mask = _h_.sha256(_vsl + b"JOCOLO_V11_MASTER").digest()[:32]
    _vmk = bytes(_a ^ _b for _a, _b in zip(bytes.fromhex(__JKEY__), _vmk_mask))
    del _vmk_mask

    _vaes_key = _hkdf(_vmk, 32, _vsl + b"aes", b"aes256gcm-key-v11")
    _vcc_key = _hkdf(_vmk, 32, _vsl + b"cc20", b"chacha20-key-v11")
    _vxor_key = _hkdf(_vmk, 16, _vsl + b"xors", b"xorshift-key-v11")
    _vshuf_key = _hkdf(_vmk, 16, _vsl + b"shuf", b"shuffle-key-v11")
    del _vmk, _vsl

    _vraw = _b_.b85decode(__JDATA__.encode("ascii"))
    _vs1 = _bun(_vraw, _vshuf_key)
    del _vraw, _vshuf_key
    _vs2 = _xss(_vs1, _vxor_key)
    del _vs1, _vxor_key
    _nonce_cc = _vs2[:12]
    _vs3_rest = _vs2[12:]
    _vs3 = _cc20d(_vs3_rest, _vcc_key, _nonce_cc)
    del _vs2, _nonce_cc, _vs3_rest, _vcc_key
    _nonce_aes = _vs3[:12]
    _tag_aes = _vs3[12:28]
    _vs4_ct = _vs3[28:]
    _vs4 = _agd(_vaes_key, _nonce_aes, _vs4_ct, _tag_aes)
    del _vs3, _nonce_aes, _tag_aes, _vs4_ct, _vaes_key
    _vpkg = _z_.decompress(_vs4)
    del _vs4
except Exception:
    _s_.exit(1)

try:
    _code = _m_.loads(_vpkg)
    del _vpkg
except Exception:
    _s_.exit(2)

_exec_ns = {"__name__": "__main__", "__builtins__": __builtins__, "__file__": __file__}
try:
    exec(_code, _exec_ns)
except SystemExit:
    raise
except Exception:
    _s_.exit(3)
